func TestReplayableBody_IndependentReadersFromCurrentOffset(t *testing.T) {
	t.Parallel()

	body := io.NewSectionReader(strings.NewReader("abcdef"), 0, 6)
	if _, err := body.Seek(2, io.SeekStart); err != nil {
		t.Fatalf("seek: %v", err)
	}
	req, err := http.NewRequest(http.MethodPost, "https://example.test", body)
	if err != nil {
		t.Fatalf("NewRequest error: %v", err)
	}
	if req.GetBody != nil {
		t.Fatalf("precondition: net/http should not know how to replay an io.SectionReader")
	}

	if closer := replayableBody(req, body); closer != nil {
		t.Fatalf("expected no closer for a body without Close, got %T", closer)
	}
	if req.ContentLength != 4 {
		t.Fatalf("expected Content-Length 4, got %d", req.ContentLength)
	}

	// A replay reader obtained before the first body is consumed must not
	// observe reads made through the first body, and vice versa.
	replay, err := req.GetBody()
	if err != nil {
		t.Fatalf("GetBody error: %v", err)
	}
	head := make([]byte, 2)
	if _, err := io.ReadFull(req.Body, head); err != nil {
		t.Fatalf("read body: %v", err)
	}
	replayed, err := io.ReadAll(replay)
	if err != nil {
		t.Fatalf("read replay: %v", err)
	}
	rest, err := io.ReadAll(req.Body)
	if err != nil {
		t.Fatalf("read rest of body: %v", err)
	}
	if string(head)+string(rest) != "cdef" {
		t.Fatalf("unexpected first body %q", string(head)+string(rest))
	}
	if string(replayed) != "cdef" {
		t.Fatalf("unexpected replayed body %q", replayed)
	}
}

func TestReplayableBody_ReturnsOriginalCloser(t *testing.T) {
	t.Parallel()

	path := filepath.Join(t.TempDir(), "body.bin")
	if err := os.WriteFile(path, []byte("payload"), 0o600); err != nil {
		t.Fatalf("write file: %v", err)
	}
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open file: %v", err)
	}
	defer f.Close()

	req, err := http.NewRequest(http.MethodPost, "https://example.test", f)
	if err != nil {
		t.Fatalf("NewRequest error: %v", err)
	}
	closer := replayableBody(req, f)
	if closer != io.Closer(f) {
		t.Fatalf("expected the file to be returned for closing, got %T", closer)
	}
	if req.Body == io.ReadCloser(f) {
		t.Fatalf("expected the transport to receive a wrapper, not the file itself")
	}
	// Closing what the transport sees must not close the caller's file,
	// otherwise a retry could not read it again.
	if err := req.Body.Close(); err != nil {
		t.Fatalf("close body: %v", err)
	}
	replay, err := req.GetBody()
	if err != nil {
		t.Fatalf("GetBody error: %v", err)
	}
	data, err := io.ReadAll(replay)
	if err != nil {
		t.Fatalf("read replay: %v", err)
	}
	if string(data) != "payload" {
		t.Fatalf("unexpected replay %q", data)
	}
}

func TestReplayableBody_LeavesOtherBodiesAlone(t *testing.T) {
	t.Parallel()

	t.Run("already replayable", func(t *testing.T) {
		t.Parallel()
		body := strings.NewReader("known")
		req, err := http.NewRequest(http.MethodPost, "https://example.test", body)
		if err != nil {
